    let rect = Annotation.textBoundingRect(
        origin: CGPoint(x: 10, y: 20), width: 200, content: "", fontSize: 24
    )
    // Minimum height = fontSize * 1.5 = 36
    XCTAssertGreaterThanOrEqual(rect.height, 36)
}

